#!/usr/bin/env python3
import json
import sys
from datetime import datetime

def parse_timestamp(ts_str):
    return datetime.fromisoformat(ts_str.replace('Z', '+00:00'))

def summarize_receipts(protocol, receipts):
    if not receipts:
        return {"protocol": protocol, "accepted_count": 0, "duplicate_count": 0}

    deliveries = {}
    for receipt in receipts:
        key = (receipt["account_id"], receipt["delivery_id"])
        if key not in deliveries:
            deliveries[key] = []
        deliveries[key].append(receipt)

    accepted_count = 0
    duplicate_count = 0

    for receipts_for_delivery in deliveries.values():
        accepted = min(
            receipts_for_delivery,
            key=lambda r: (parse_timestamp(r["occurred_at"]), r["record_id"])
        )
        accepted_count += 1
        duplicate_count += len(receipts_for_delivery) - 1

    return {"protocol": protocol, "accepted_count": accepted_count, "duplicate_count": duplicate_count}

def run(q):
    if q.get("command") == "ping":
        return {"status": "ok", "product": "Courier Relay"}

    if q.get("command") == "count":
        protocol = q.get("protocol", "1")
        receipts = q.get("receipts", [])
        return summarize_receipts(protocol, receipts)

    if q.get("command") == "summary":
        protocol = q.get("protocol", "1")
        receipts = q.get("receipts", [])
        return summarize_receipts(protocol, receipts)

    return {"error": "unknown_command"}

if __name__ == "__main__":
    print(json.dumps(run(json.load(sys.stdin))))

"""Run one supplied public case file against the local application/artifacts."""
import argparse
import json
from pathlib import Path
import subprocess
import sys


def equal(left, right):
    if type(left) is not type(right):
        return False
    if isinstance(left, dict):
        return left.keys() == right.keys() and all(equal(left[k], right[k]) for k in left)
    if isinstance(left, list):
        return len(left) == len(right) and all(equal(a, b) for a, b in zip(left, right))
    return left == right


parser = argparse.ArgumentParser()
parser.add_argument("--cases", required=True)
args = parser.parse_args()
failed = 0
for case in json.loads(Path(args.cases).read_text()):
    try:
        if "artifact_json_path" in case:
            got = json.loads(Path(case["artifact_json_path"]).read_text())
        else:
            proc = subprocess.run([sys.executable, "main.py"], input=json.dumps(case["request"]),
                                  capture_output=True, text=True, check=True, timeout=5)
            got = json.loads(proc.stdout)
        ok = equal(got, case["expected"])
    except (OSError, ValueError, subprocess.SubprocessError) as exc:
        ok = False
        got = str(exc)
    print(("PASS " if ok else "FAIL ") + case["name"])
    if not ok:
        print(" expected:", case["expected"])
        print(" received:", got)
        failed += 1
raise SystemExit(bool(failed))

